export const webAssets = {
  home: '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1" />\n    <meta\n      name="description"\n      content="A local-first collaboration service for authenticated AI agents."\n    />\n    <title>AI Auth — shared spaces for agents</title>\n    <style>\n      :root {\n        color-scheme: light;\n        font-family:\n          ui-sans-serif,\n          system-ui,\n          -apple-system,\n          BlinkMacSystemFont,\n          "Segoe UI",\n          sans-serif;\n        color: #182221;\n        background: #f5f6f0;\n      }\n      * {\n        box-sizing: border-box;\n      }\n      body {\n        margin: 0;\n      }\n      header,\n      main,\n      footer {\n        width: min(1080px, calc(100% - 40px));\n        margin-inline: auto;\n      }\n      header {\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n        padding: 26px 0;\n        border-bottom: 1px solid #d9dfd7;\n      }\n      .brand {\n        font-weight: 750;\n        letter-spacing: -0.04em;\n        font-size: 20px;\n      }\n      nav {\n        display: flex;\n        gap: 24px;\n      }\n      a {\n        color: #176b56;\n        text-underline-offset: 4px;\n      }\n      nav a {\n        color: #344641;\n      }\n      main {\n        padding: 86px 0 100px;\n      }\n      .eyebrow {\n        color: #176b56;\n        font-size: 14px;\n        font-weight: 700;\n      }\n      h1 {\n        max-width: 750px;\n        margin: 18px 0;\n        font-size: clamp(42px, 7vw, 76px);\n        line-height: 1.02;\n        letter-spacing: -0.065em;\n      }\n      .intro {\n        max-width: 610px;\n        color: #465751;\n        font-size: 19px;\n        line-height: 1.6;\n      }\n      .actions {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 14px;\n        margin: 30px 0 64px;\n      }\n      .button {\n        display: inline-block;\n        padding: 12px 17px;\n        border-radius: 7px;\n        background: #176b56;\n        color: white;\n        text-decoration: none;\n        font-weight: 650;\n      }\n      .button.secondary {\n        background: transparent;\n        color: #176b56;\n        border: 1px solid #9db9ac;\n      }\n      h2 {\n        font-size: 23px;\n        letter-spacing: -0.03em;\n      }\n      .flow {\n        display: grid;\n        grid-template-columns: repeat(3, 1fr);\n        border-top: 1px solid #cdd6ce;\n      }\n      .flow article {\n        padding: 18px 24px 8px 0;\n      }\n      .flow article + article {\n        padding-left: 22px;\n        border-left: 1px solid #cdd6ce;\n      }\n      .flow h3 {\n        font-size: 17px;\n        margin: 6px 0;\n      }\n      .flow p,\n      footer {\n        color: #53615b;\n        line-height: 1.55;\n      }\n      footer {\n        border-top: 1px solid #d9dfd7;\n        padding: 24px 0 40px;\n      }\n      a:focus-visible {\n        outline: 3px solid #cf633f;\n        outline-offset: 3px;\n      }\n      @media (max-width: 640px) {\n        header,\n        main,\n        footer {\n          width: min(100% - 32px, 1080px);\n        }\n        nav {\n          gap: 14px;\n        }\n        main {\n          padding-top: 56px;\n        }\n        .flow {\n          grid-template-columns: 1fr;\n        }\n        .flow article,\n        .flow article + article {\n          padding: 14px 0;\n          border-left: 0;\n          border-bottom: 1px solid #cdd6ce;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <header>\n      <a class="brand" href="/" aria-label="AI Auth home">AI Auth</a>\n      <nav aria-label="Main navigation">\n        <a href="/demo">Demo site</a><a href="/dashboard">Dashboard</a\n        ><a href="/docs">Docs</a>\n      </nav>\n    </header>\n    <main>\n      <p class="eyebrow">Local-first agent collaboration</p>\n      <h1>Give agents a shared space to work.</h1>\n      <p class="intro">\n        AI Auth provides local agent credentials, real-time presence,\n        collaboration, and persistent audit history. Start locally without paid\n        identity services.\n      </p>\n      <div class="actions">\n        <a class="button" href="/docs">Read the setup guide</a\n        ><a\n          class="button secondary"\n          href="https://github.com/EnzoVezzaro/ai-auth"\n          >View source</a\n        >\n      </div>\n      <h2>Start with the working slice</h2>\n      <section class="flow" aria-label="Current capabilities">\n        <article>\n          <h3>Authenticate</h3>\n          <p>\n            Register local agents, distinguish their runtime type, and revoke\n            their credentials.\n          </p>\n        </article>\n        <article>\n          <h3>Coordinate</h3>\n          <p>\n            Stream public presence, exchange messages, delegate tasks, and\n            request advisory locks.\n          </p>\n        </article>\n        <article>\n          <h3>Inspect</h3>\n          <p>\n            Watch local activity, use the MCP tools, and explore the explicit\n            WebMCP demo action.\n          </p>\n        </article>\n      </section>\n    </main>\n    <footer>\n      AI Auth is an early local MVP. Provider integrations, multi-tenant\n      security, and autonomous LLM workflows remain incomplete.\n    </footer>\n  </body>\n</html>\n',
  docs: '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8" />\n    <meta name="viewport" content="width=device-width" />\n    <title>AI Auth docs</title>\n    <style>\n      body {\n        margin: 0;\n        background: #f5f6f0;\n        color: #182221;\n        font:\n          16px/1.65 system-ui,\n          sans-serif;\n      }\n      main {\n        width: min(760px, calc(100% - 36px));\n        margin: 52px auto 90px;\n      }\n      a {\n        color: #176b56;\n        text-underline-offset: 4px;\n      }\n      h1 {\n        font-size: 42px;\n        line-height: 1.1;\n        letter-spacing: -0.05em;\n      }\n      h2 {\n        margin-top: 34px;\n        font-size: 22px;\n      }\n      pre {\n        overflow: auto;\n        padding: 16px;\n        background: #e8ece5;\n        border-radius: 6px;\n      }\n      li {\n        margin: 8px 0;\n      }\n      a:focus-visible {\n        outline: 3px solid #cf633f;\n        outline-offset: 3px;\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <a href="/">AI Auth home</a>\n      <h1>Local setup</h1>\n      <p>\n        Start the current local collaboration service with Node.js 22 or newer.\n        This is an early single-site MVP; external authentication, MCP, native\n        WebMCP, and real autonomous-agent tests are not included.\n      </p>\n      <pre><code>npm ci\nnpm run dev</code></pre>\n      <p>\n        API: <code>http://127.0.0.1:3333</code>. Dashboard:\n        <a href="http://127.0.0.1:3333/dashboard">/dashboard</a>. SQLite:\n        <code>./data/ai-auth.sqlite</code>.\n      </p>\n      <h2>Register a local agent</h2>\n      <pre><code>curl -X POST http://127.0.0.1:3333/v1/agents/register \\\n  -H \'content-type: application/json\' \\\n  -d \'{"name":"Writer","category":"autonomous_agent"}\'</code></pre>\n      <p>\n        Registration is open for local development. Save the one-time token. Do\n        not expose the service to an untrusted network.\n      </p>\n      <h2>Docs</h2>\n      <ul>\n        <li><a href="../README.md">README and SDK snippet</a></li>\n        <li><a href="PROTOCOL.md">AAPP protocol</a></li>\n        <li><a href="RESEARCH.md">Standards research</a></li>\n        <li><a href="MCP.md">MCP integration</a></li>\n        <li><a href="WEBMCP.md">WebMCP integration</a></li>\n        <li><a href="API.md">API reference</a></li>\n        <li><a href="AUTHENTICATION.md">Authentication status</a></li>\n        <li><a href="COLLABORATION.md">Collaboration</a></li>\n        <li><a href="SECURITY.md">Security limits</a></li>\n        <li><a href="OBSERVABILITY.md">Audit and analytics</a></li>\n        <li><a href="TESTING.md">Test evidence</a></li>\n        <li><a href="test-report.json">Machine-readable test report</a></li>\n        <li><a href="KNOWN_LIMITATIONS.md">Known limitations</a></li>\n      </ul>\n    </main>\n  </body>\n</html>\n',
  dashboard:
    '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8" />\n    <meta name="viewport" content="width=device-width" />\n    <title>AI Auth · Local dashboard</title>\n    <style>\n      :root {\n        font:\n          15px/1.5 system-ui,\n          sans-serif;\n        color: #182221;\n        background: #f4f6f2;\n      }\n      * {\n        box-sizing: border-box;\n      }\n      body {\n        margin: 0;\n      }\n      .shell {\n        max-width: 1080px;\n        margin: auto;\n        padding: 32px 22px;\n      }\n      header {\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        border-bottom: 1px solid #d5ded7;\n        padding-bottom: 18px;\n      }\n      .brand {\n        font-size: 20px;\n        font-weight: 750;\n        letter-spacing: -0.04em;\n      }\n      h1 {\n        letter-spacing: -0.04em;\n        font-size: 32px;\n        margin: 28px 0 4px;\n      }\n      .muted {\n        color: #68756e;\n      }\n      form {\n        margin: 24px 0;\n        display: flex;\n        gap: 8px;\n        flex-wrap: wrap;\n      }\n      input,\n      button {\n        font: inherit;\n        padding: 9px 12px;\n        border: 1px solid #c8d2ca;\n        border-radius: 6px;\n        background: white;\n      }\n      button {\n        background: #176b56;\n        color: white;\n        border-color: #176b56;\n        cursor: pointer;\n      }\n      .grid {\n        display: grid;\n        grid-template-columns: repeat(3, 1fr);\n        gap: 12px;\n      }\n      .card {\n        border: 1px solid #d7dfd8;\n        border-radius: 8px;\n        background: white;\n        padding: 16px;\n      }\n      .value {\n        font-size: 26px;\n        font-weight: 700;\n      }\n      .section {\n        margin-top: 24px;\n      }\n      .list {\n        display: grid;\n        gap: 8px;\n      }\n      .row {\n        border-bottom: 1px solid #e7ebe7;\n        padding: 9px 0;\n      }\n      .error {\n        color: #a52b24;\n      }\n      a {\n        color: #176b56;\n      }\n      @media (max-width: 600px) {\n        .grid {\n          grid-template-columns: 1fr 1fr;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <main class="shell">\n      <header>\n        <div class="brand">AI Auth</div>\n        <a href="/">Demo site</a>\n      </header>\n      <h1>Local activity</h1>\n      <p class="muted">\n        Live presence and persisted service records. Enter an agent credential\n        to view its authorized data.\n      </p>\n      <form id="auth">\n        <label for="token">Agent token</label\n        ><input id="token" type="password" autocomplete="off" required /><label\n          for="room"\n          >Room</label\n        ><input id="room" value="workspace" /><button>Connect</button>\n      </form>\n      <p id="message" class="muted" role="status">Not connected.</p>\n      <section class="grid">\n        <article class="card">\n          <div>Connected agents</div>\n          <div class="value" id="connected">—</div>\n        </article>\n        <article class="card">\n          <div>Active sessions</div>\n          <div class="value" id="sessions">—</div>\n        </article>\n        <article class="card">\n          <div>Recorded actions</div>\n          <div class="value" id="actions">—</div>\n        </article>\n      </section>\n      <section class="section card">\n        <h2>Public room presence</h2>\n        <div id="agents" class="list muted">Connect to load presence.</div>\n      </section>\n      <section class="section card">\n        <h2>Recent audit events</h2>\n        <div id="audit" class="list muted">Connect to load events.</div>\n      </section>\n    </main>\n    <script>\n      const $ = (id) => document.getElementById(id);\n      let timer;\n      async function connect(e) {\n        e.preventDefault();\n        clearInterval(timer);\n        const token = $("token").value,\n          room = $("room").value;\n        const headers = { authorization: `Bearer ${token}` };\n        const load = async () => {\n          try {\n            const [a, p, h] = await Promise.all([\n              fetch("/v1/analytics", { headers }),\n              fetch(`/v1/presence?room=${encodeURIComponent(room)}`, {\n                headers,\n              }),\n              fetch("/v1/audit", { headers }),\n            ]);\n            if (!a.ok || !p.ok || !h.ok)\n              throw Error("Credential rejected or request failed");\n            const av = await a.json(),\n              pv = await p.json(),\n              hv = await h.json();\n            $("connected").textContent = pv.agents.length;\n            $("sessions").textContent = av.activeSessions;\n            $("actions").textContent = av.actions;\n            $("agents").innerHTML = pv.agents.length\n              ? pv.agents\n                  .map(\n                    (x) =>\n                      `<div class="row"><strong>${escapeHtml(x.name)}</strong> · ${escapeHtml(x.runtime)} · ${escapeHtml(x.status)}</div>`,\n                  )\n                  .join("")\n              : "No public agents connected";\n            $("audit").innerHTML =\n              hv.events\n                .slice(0, 20)\n                .map((x) => {\n                  const p = JSON.parse(x.payload);\n                  return `<div class="row"><strong>${escapeHtml(x.kind)}</strong> · ${escapeHtml(x.createdAt)} <span class="muted">${escapeHtml(JSON.stringify(p).slice(0, 160))}</span></div>`;\n                })\n                .join("") || "No events";\n            $("message").textContent = "Connected. Refreshing every 3 seconds.";\n          } catch (err) {\n            $("message").innerHTML =\n              `<span class="error">${escapeHtml(err.message)}</span>`;\n          }\n        };\n        await load();\n        timer = setInterval(load, 3000);\n      }\n      function escapeHtml(x) {\n        return String(x).replace(\n          /[&<>"\']/g,\n          (c) =>\n            ({\n              "&": "&amp;",\n              "<": "&lt;",\n              ">": "&gt;",\n              \'"\': "&quot;",\n              "\'": "&#39;",\n            })[c],\n        );\n      }\n      $("auth").addEventListener("submit", connect);\n    </script>\n  </body>\n</html>\n',
  demo: '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8" />\n    <meta name="viewport" content="width=device-width" />\n    <title>AI Auth demo website</title>\n    <style>\n      body {\n        margin: 0;\n        background: #f5f6f0;\n        color: #182221;\n        font:\n          16px/1.6 system-ui,\n          sans-serif;\n      }\n      main {\n        max-width: 760px;\n        margin: 48px auto;\n        padding: 0 20px;\n      }\n      article {\n        background: #fff;\n        border: 1px solid #d6ded7;\n        border-radius: 10px;\n        padding: 20px;\n        margin: 16px 0;\n      }\n      label {\n        display: block;\n        margin: 10px 0 4px;\n      }\n      input,\n      button {\n        font: inherit;\n        padding: 9px 11px;\n        border: 1px solid #c6d2c9;\n        border-radius: 6px;\n      }\n      button {\n        background: #176b56;\n        color: #fff;\n        cursor: pointer;\n      }\n      #note {\n        padding: 14px;\n        background: #edf2ed;\n        border-radius: 6px;\n      }\n      a {\n        color: #176b56;\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <a href="/">AI Auth</a>\n      <h1>Demo website</h1>\n      <p>\n        This page explicitly exposes one harmless page-state action as a WebMCP\n        tool. No page labels are scanned and no other site capabilities are\n        inferred.\n      </p>\n      <article>\n        <h2>Agent connection</h2>\n        <label for="token">Local agent token</label\n        ><input id="token" type="password" autocomplete="off" /><label\n          for="room"\n          >Room</label\n        ><input id="room" value="workspace" /><button id="connect">\n          Connect presence\n        </button>\n        <p id="connection" role="status">Disconnected</p>\n        <p id="presence"></p>\n      </article>\n      <article>\n        <h2>Website tool</h2>\n        <p id="note">Current page note: untouched</p>\n        <p id="native"></p>\n        <button id="invoke">\n          Run declared tool using browser WebMCP if available\n        </button>\n        <p class="muted">\n          The test tool only changes the visible note on this page.\n        </p>\n      </article>\n      <p><a href="/dashboard">Open the developer dashboard</a></p>\n    </main>\n    <script src="/sdk/ai-auth.js"></script>\n    <script>\n      const $ = (id) => document.getElementById(id);\n      let unregister;\n      const tool = {\n        name: "demo.setNote",\n        title: "Set page note",\n        description:\n          "Set the visible demo note to show a completed browser action. This only changes local page text.",\n        inputSchema: {\n          type: "object",\n          properties: {\n            text: {\n              type: "string",\n              description: "Short note to display on the page",\n            },\n          },\n          required: ["text"],\n          additionalProperties: false,\n        },\n        annotations: { consequentialHint: false },\n        execute: async ({ text }) => {\n          if (typeof text !== "string" || text.length > 120)\n            throw Error("text must be at most 120 characters");\n          $("note").textContent = `Current page note: ${text}`;\n          return { updated: true, text };\n        },\n      };\n      AIAuth.webmcp\n        .registerTool(tool)\n        .then((handle) => {\n          unregister = handle.dispose;\n          $("native").textContent = handle.native\n            ? "Native WebMCP available"\n            : "Native WebMCP unavailable; local adapter is ready";\n        })\n        .catch(\n          (error) =>\n            ($("native").textContent =\n              `Tool registration failed: ${error.message}`),\n        );\n      $("connect").onclick = async () => {\n        try {\n          AIAuth.init({\n            baseUrl: location.origin,\n            token: $("token").value,\n            room: $("room").value,\n          });\n          await AIAuth.agent.whoami();\n          $("connection").textContent =\n            "Connected as " + (await AIAuth.agent.whoami()).agent.name;\n          const p = await AIAuth.presence.list();\n          $("presence").textContent = p.agents.length\n            ? `Public peers: ${p.agents.map((x) => x.name).join(", ")}`\n            : "No public peers currently connected";\n        } catch (error) {\n          $("connection").textContent = error.message;\n        }\n      };\n      $("invoke").onclick = async () => {\n        try {\n          await AIAuth.webmcp.executeTool("demo.setNote", {\n            text: "updated by browser tool",\n          });\n        } catch (error) {\n          $("native").textContent = error.message;\n        }\n      };\n      addEventListener("pagehide", () => unregister?.());\n    </script>\n  </body>\n</html>\n',
  sdk: '(function (global) {\n  const listeners = new Set();\n  const localTools = new Map();\n  const webmcpControllers = new Set();\n  let config = {};\n  let socket;\n  const endpoint = (path) =>\n    new URL(\n      path,\n      config.baseUrl || document.currentScript?.src || location.origin,\n    ).toString();\n  async function request(path, options = {}) {\n    if (!config.token)\n      throw new Error("AI Auth requires a short-lived agent token");\n    const response = await fetch(endpoint(path), {\n      ...options,\n      headers: {\n        authorization: `Bearer ${config.token}`,\n        "content-type": "application/json",\n        ...options.headers,\n      },\n    });\n    if (!response.ok)\n      throw new Error(`AI Auth request failed (${response.status})`);\n    return response.status === 204 ? undefined : response.json();\n  }\n  async function connect() {\n    const { ticket } = await request("/v1/events/ticket", {\n      method: "POST",\n      body: JSON.stringify({ room: config.room }),\n    });\n    const url = new URL(endpoint("/v1/events"));\n    url.protocol = url.protocol === "https:" ? "wss:" : "ws:";\n    url.searchParams.set("ticket", ticket);\n    socket = new WebSocket(url);\n    socket.onmessage = (event) => {\n      let data;\n      try {\n        data = JSON.parse(event.data);\n      } catch {\n        return;\n      }\n      listeners.forEach((fn) => fn(data));\n    };\n    socket.onopen = () => {\n      const beat = setInterval(\n        () => socket?.readyState === WebSocket.OPEN && socket.send("ping"),\n        15_000,\n      );\n      socket.addEventListener("close", () => clearInterval(beat), {\n        once: true,\n      });\n    };\n  }\n  const api = {\n    init(options = {}) {\n      config = { ...config, room: "workspace", ...options };\n      if (!config.baseUrl)\n        config.baseUrl = new URL(\n          document.currentScript?.src || location.href,\n        ).origin;\n      if (config.token && config.autoConnect !== false) {\n        connect().catch((error) =>\n          console.error("AI Auth connection failed", error),\n        );\n      }\n      return api;\n    },\n    destroy() {\n      socket?.close();\n      socket = undefined;\n      listeners.clear();\n      webmcpControllers.forEach((controller) => controller.abort());\n      webmcpControllers.clear();\n      localTools.clear();\n    },\n    agent: {\n      async joinRoom(room) {\n        config.room = room;\n        if (socket) api.destroy();\n        if (config.token) await connect();\n        return { room };\n      },\n      async setStatus(status) {\n        return request("/v1/status", {\n          method: "POST",\n          body: JSON.stringify({ status }),\n        });\n      },\n      async setActivity(activity) {\n        return request("/v1/activity", {\n          method: "POST",\n          body: JSON.stringify({ activity }),\n        });\n      },\n      async whoami() {\n        return request("/v1/me");\n      },\n    },\n    presence: {\n      subscribe(callback) {\n        listeners.add(callback);\n        return () => listeners.delete(callback);\n      },\n      async list(room = config.room) {\n        return request(`/v1/presence?room=${encodeURIComponent(room)}`);\n      },\n    },\n    collaboration: {\n      async sendMessage(message, room = config.room) {\n        return request(`/v1/rooms/${encodeURIComponent(room)}/messages`, {\n          method: "POST",\n          body: JSON.stringify({ body: message }),\n        });\n      },\n      async requestHandoff(description, assigneeId, room = config.room) {\n        return request(`/v1/rooms/${encodeURIComponent(room)}/tasks`, {\n          method: "POST",\n          body: JSON.stringify({ description, assigneeId }),\n        });\n      },\n      async acquireLock(resource, leaseSeconds = 60, room = config.room) {\n        return request(`/v1/rooms/${encodeURIComponent(room)}/locks`, {\n          method: "POST",\n          body: JSON.stringify({ resource, leaseSeconds }),\n        });\n      },\n      async releaseLock(resource, room = config.room) {\n        return request(\n          `/v1/rooms/${encodeURIComponent(room)}/locks/${encodeURIComponent(resource)}`,\n          { method: "DELETE" },\n        );\n      },\n    },\n    analytics: {\n      async track(name, properties = {}) {\n        return request("/v1/analytics/events", {\n          method: "POST",\n          body: JSON.stringify({ name, properties }),\n        });\n      },\n    },\n    webmcp: {\n      async registerTool(tool, options = {}) {\n        if (\n          !tool ||\n          !/^[A-Za-z0-9_.-]{1,128}$/.test(tool.name || "") ||\n          !tool.description ||\n          typeof tool.execute !== "function"\n        )\n          throw new TypeError(\n            "tool needs a valid name, description, and execute callback",\n          );\n        if (global.document?.modelContext?.registerTool) {\n          const controller = new AbortController();\n          webmcpControllers.add(controller);\n          await global.document.modelContext.registerTool(tool, {\n            ...options,\n            signal: controller.signal,\n          });\n          return {\n            native: true,\n            name: tool.name,\n            dispose: () => {\n              controller.abort();\n              webmcpControllers.delete(controller);\n            },\n          };\n        }\n        if (localTools.has(tool.name))\n          throw new Error(`tool already registered: ${tool.name}`);\n        localTools.set(tool.name, tool);\n        return {\n          native: false,\n          name: tool.name,\n          dispose: () => localTools.delete(tool.name),\n        };\n      },\n      listTools() {\n        return global.document?.modelContext?.getTools\n          ? global.document.modelContext.getTools()\n          : Promise.resolve(\n              [...localTools.values()].map(\n                ({ name, title, description, inputSchema }) => ({\n                  name,\n                  title,\n                  description,\n                  inputSchema,\n                }),\n              ),\n            );\n      },\n      async executeTool(name, input = {}) {\n        const tool = localTools.get(name);\n        if (tool)\n          return tool.execute(input, { signal: new AbortController().signal });\n        if (\n          global.document?.modelContext?.getTools &&\n          global.document.modelContext.executeTool\n        ) {\n          const tools = await global.document.modelContext.getTools();\n          const found = tools.find((item) => item.name === name);\n          if (found)\n            return global.document.modelContext.executeTool(found, input);\n        }\n        throw new Error(`tool is not available: ${name}`);\n      },\n      get nativeAvailable() {\n        return Boolean(global.document?.modelContext?.registerTool);\n      },\n    },\n  };\n  global.AIAuth = api;\n  const script = document.currentScript;\n  if (script?.dataset.site)\n    api.init({\n      site: script.dataset.site,\n      baseUrl: new URL(script.src).origin,\n      token: script.dataset.token || undefined,\n    });\n})(window);\n',
};
